class Solution {
public:
    bool possibleToStamp(vector<vector<int>>& grid, int stampHeight, int stampWidth) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> pref(m + 1, vector<int>(n + 1, 0));
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                pref[r + 1][c + 1] = pref[r][c + 1] + pref[r + 1][c] - pref[r][c] + grid[r][c];
            }
        }
        auto query = [&](int r1, int c1, int r2, int c2) {
            return pref[r2 + 1][c2 + 1] - pref[r1][c2 + 1] - pref[r2 + 1][c1] + pref[r1][c1];
        };
        vector<vector<int>> diff(m + 2, vector<int>(n + 2, 0));
        for (int r = 0; r <= m - stampHeight; r++) {
            for (int c = 0; c <= n - stampWidth; c++) {
                if (query(r, c, r + stampHeight - 1, c + stampWidth - 1) == 0) {
                    diff[r + 1][c + 1]++;
                    diff[r + stampHeight + 1][c + 1]--;
                    diff[r + 1][c + stampWidth + 1]--;
                    diff[r + stampHeight + 1][c + stampWidth + 1]++;
                }
            }
        }
        vector<vector<int>> covered(m + 2, vector<int>(n + 2, 0));
        for (int r = 1; r <= m; r++) {
            for (int c = 1; c <= n; c++) {
                covered[r][c] = covered[r - 1][c] + covered[r][c - 1] - covered[r - 1][c - 1] + diff[r][c];
                if (grid[r - 1][c - 1] == 0 && covered[r][c] == 0) return false;
            }
        }
        return true;
    }
};

class Solution {
    public boolean possibleToStamp(int[][] grid, int stampHeight, int stampWidth) {
        int m = grid.length, n = grid[0].length;
        int[][] pref = new int[m + 1][n + 1];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                pref[r + 1][c + 1] = pref[r][c + 1] + pref[r + 1][c] - pref[r][c] + grid[r][c];
            }
        }
        int[][] diff = new int[m + 2][n + 2];
        for (int r = 0; r <= m - stampHeight; r++) {
            for (int c = 0; c <= n - stampWidth; c++) {
                int sum = pref[r + stampHeight][c + stampWidth] - pref[r][c + stampWidth] - pref[r + stampHeight][c] + pref[r][c];
                if (sum == 0) {
                    diff[r + 1][c + 1]++;
                    diff[r + stampHeight + 1][c + 1]--;
                    diff[r + 1][c + stampWidth + 1]--;
                    diff[r + stampHeight + 1][c + stampWidth + 1]++;
                }
            }
        }
        int[][] covered = new int[m + 2][n + 2];
        for (int r = 1; r <= m; r++) {
            for (int c = 1; c <= n; c++) {
                covered[r][c] = covered[r - 1][c] + covered[r][c - 1] - covered[r - 1][c - 1] + diff[r][c];
                if (grid[r - 1][c - 1] == 0 && covered[r][c] == 0) return false;
            }
        }
        return true;
    }
}

