        }
    }
    const diff = Array.from({ length: m + 2 }, () => new Int32Array(n + 2));
    for (let r = 0; r <= m - stampHeight; r++) {
        for (let c = 0; c <= n - stampWidth; c++) {
            const sum = pref[r + stampHeight][c + stampWidth] - pref[r][c + stampWidth] - pref[r + stampHeight][c] + pref[r][c];
            if (sum === 0) {
                diff[r + 1][c + 1]++;
                diff[r + stampHeight + 1][c + 1]--;
                diff[r + 1][c + stampWidth + 1]--;
                diff[r + stampHeight + 1][c + stampWidth + 1]++;
            }
        }
    }
